import React, { useState, useEffect } from "react";
import {
  Box,
  Typography,
  Avatar,
  Container,
  Paper,
  TextField,
  Button,
  CircularProgress,
  Snackbar,
  Alert,
  Grid,
  IconButton,
} from "@mui/material";
import { Edit as EditIcon, Save as SaveIcon } from "@mui/icons-material";
import { apiRequest } from "../utils/apiRequest";
import { API } from "../api/endpoints";

const Profile = () => {
  const [userData, setUserData] = useState(null);
  const [editMode, setEditMode] = useState(false);
  const [formData, setFormData] = useState({
    name: "",
    profile_img: null,
  });
  const [loading, setLoading] = useState(false);
  const [snackbar, setSnackbar] = useState({
    open: false,
    message: "",
    severity: "success",
  });
  const [imagePreview, setImagePreview] = useState(null);

  useEffect(() => {
    const fetchUserProfile = async () => {
      try {
        const response = await apiRequest({
          ...API.userProfile,
        });

        const user = response?.data?.user;

        setUserData(user);

        setFormData({
          name: user?.name || "",
          profile_img: null,
        });
      } catch (error) {
        console.error("Failed to fetch user profile:", error);

        setSnackbar({
          open: true,
          message: error?.message || "Failed to load profile",
          severity: "error",
        });
      }
    };
    fetchUserProfile();
  }, []);

  const handleEditToggle = () => {
    setEditMode(!editMode);
  };

  const handleInputChange = (e) => {
    const { name, value, files } = e.target;

    if (files) {
      setFormData((prev) => ({
        ...prev,
        [name]: files[0],
      }));
      setImagePreview(URL.createObjectURL(files[0]));
    } else {
      setFormData((prev) => ({
        ...prev,
        [name]: value,
      }));
    }
  };

  const handleUpdateProfile = async () => {
    setLoading(true);

    try {
      const data = new FormData();

      data.append("name", formData.name);

      if (formData.profile_img) {
        data.append("profile_img", formData.profile_img);
      }

      const response = await apiRequest({
        ...API.updateProfile,
        data,
      });

      setUserData((prev) => ({
        ...prev,
        name: formData.name,
        profile_img: formData.profile_img
          ? URL.createObjectURL(formData.profile_img)
          : prev.profile_img,
      }));

      setEditMode(false);

      setSnackbar({
        open: true,
        message: response?.message || "Profile updated successfully",
        severity: "success",
      });
    } catch (error) {
      console.error("Failed to update profile:", error);

      setSnackbar({
        open: true,
        message: error?.message || "Failed to update profile",
        severity: "error",
      });
    } finally {
      setLoading(false);
    }
  };

  const handleSnackbarClose = () => {
    setSnackbar((prev) => ({ ...prev, open: false }));
  };

  if (!userData) {
    return (
      <Box sx={{ display: "flex", justifyContent: "center", mt: 4 }}>
        <CircularProgress size={40} sx={{ color: "#E56A14" }} />
      </Box>
    );
  }

  return (
    <Container
      maxWidth="md"
      sx={{ py: 2, display: "flex", alignItems: "center" }}
    >
      <Paper
        elevation={3}
        sx={{
          p: { xs: 1, md: 2 },
          borderRadius: 2,
          background: "linear-gradient(145deg, #ffffff, #f9f9f9)",
          boxShadow: "0 8px 16px rgba(0,0,0,0.1)",
          border: "1px solid #eee",
          width: "100%",
        }}
      >
        <Box
          sx={{
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            mb: 2,
          }}
        >
          <Box
            sx={{
              position: "relative",
              mb: 1,
            }}
          >
            <Avatar
              src={imagePreview || userData.profile_img || ""}
              alt={userData.name}
              sx={{
                width: 100,
                height: 100,
                border: "3px solid #43B02A",
                boxShadow: "0 2px 8px rgba(0,0,0,0.15)",
              }}
            >
              {!userData.profile_img && userData.name.charAt(0)}
            </Avatar>
            {editMode && (
              <IconButton
                component="label"
                sx={{
                  position: "absolute",
                  bottom: 4,
                  right: 4,
                  backgroundColor: "#E56A14",
                  color: "white",
                  "&:hover": {
                    backgroundColor: "#d15e10",
                  },
                  p: 0.5,
                }}
              >
                <EditIcon fontSize="small" />
                <input
                  type="file"
                  hidden
                  name="profile_img"
                  accept="image/*"
                  onChange={handleInputChange}
                />
              </IconButton>
            )}
          </Box>

          <Typography
            variant="h4"
            fontWeight={600}
            sx={{
              background: "linear-gradient(45deg, #E56A14 0%, #f39c12 100%)",
              WebkitBackgroundClip: "text",
              WebkitTextFillColor: "transparent",
              mb: 0.5,
            }}
          >
            {userData.name}
          </Typography>

          <Box
            sx={{
              display: "flex",
              alignItems: "center",
              backgroundColor: "#43B02A20",
              px: 1.5,
              py: 0.3,
              borderRadius: 16,
            }}
          >
            <Box
              sx={{
                width: 6,
                height: 6,
                backgroundColor: "#43B02A",
                borderRadius: "50%",
                mr: 0.5,
              }}
            />
            <Typography variant="subtitle1" color="#43B02A" fontWeight={600}>
              {userData.role.charAt(0).toUpperCase() + userData.role.slice(1)}
            </Typography>
          </Box>
        </Box>

        <Grid container spacing={2}>
          <Grid item size={{ xs: 12, sm: 12, md: 6, lg: 6, xl: 6 }}>
            <Paper
              elevation={0}
              sx={{
                p: 2,
                borderRadius: 2,
                background: "#f9f9f9",
                height: "100%",
              }}
            >
              <Typography
                variant="h6"
                fontWeight={600}
                gutterBottom
                sx={{
                  color: "#333",
                  borderBottom: "2px solid #43B02A",
                  pb: 0.5,
                  mb: 2,
                  fontSize: "24px",
                }}
              >
                Profile Information
              </Typography>

              <Box sx={{ mb: 1.5 }}>
                <Typography variant="caption" color="#666" fontWeight={500}>
                  Email Address
                </Typography>
                <Typography variant="body2" fontWeight={500}>
                  {userData.email}
                </Typography>
              </Box>

              <Box sx={{ mb: 1.5 }}>
                <Typography variant="caption" color="#666" fontWeight={500}>
                  Username
                </Typography>
                <Typography variant="body2" fontWeight={500}>
                  {userData.username}
                </Typography>
              </Box>

              <Box sx={{ mb: 1.5 }}>
                <Typography variant="caption" color="#666" fontWeight={500}>
                  Department
                </Typography>
                <Typography variant="body2" fontWeight={500}>
                  {userData.department?.name || "N/A"}
                </Typography>
              </Box>

              <Box sx={{ mb: 1.5 }}>
                <Typography variant="caption" color="#666" fontWeight={500}>
                  Location
                </Typography>
                <Typography variant="body2" fontWeight={500}>
                  {userData.location?.name || "N/A"}
                </Typography>
              </Box>
            </Paper>
          </Grid>

          {editMode ? (
            <Grid item size={{ xs: 12, sm: 12, md: 6, lg: 6, xl: 6 }}>
              <Paper
                elevation={0}
                sx={{
                  p: 2,
                  borderRadius: 2,
                  background: "#f9f9f9",
                  height: "100%",
                }}
              >
                <Typography
                  variant="h6"
                  fontWeight={600}
                  gutterBottom
                  sx={{
                    color: "#333",
                    borderBottom: "2px solid #E56A14",
                    pb: 0.5,
                    mb: 2,
                  }}
                >
                  Edit Profile
                </Typography>

                <TextField
                  fullWidth
                  name="name"
                  label="Full Name"
                  value={formData.name}
                  onChange={handleInputChange}
                  variant="outlined"
                  sx={{ mb: 2 }}
                  InputProps={{
                    sx: {
                      borderRadius: 2,
                      backgroundColor: "#fff",
                      fontSize: "0.875rem",
                    },
                  }}
                  InputLabelProps={{
                    sx: { fontSize: "0.875rem" },
                  }}
                />

                <Box sx={{ display: "flex", gap: 1, mt: 2 }}>
                  <Button
                    variant="contained"
                    onClick={handleUpdateProfile}
                    disabled={loading}
                    startIcon={
                      loading ? (
                        <CircularProgress size={16} sx={{ color: "white" }} />
                      ) : (
                        <SaveIcon fontSize="small" />
                      )
                    }
                    sx={{
                      flex: 1,
                      py: 1,
                      borderRadius: 2,
                      textTransform: "none",
                      fontSize: "0.875rem",
                      fontWeight: 600,
                      backgroundColor: "#E56A14",
                      "&:hover": {
                        backgroundColor: "#d15e10",
                        boxShadow: "0 2px 6px rgba(229, 106, 20, 0.3)",
                      },
                    }}
                  >
                    Save
                  </Button>

                  <Button
                    variant="outlined"
                    onClick={handleEditToggle}
                    disabled={loading}
                    sx={{
                      flex: 1,
                      py: 1,
                      borderRadius: 2,
                      textTransform: "none",
                      fontSize: "0.875rem",
                      fontWeight: 600,
                      color: "#666",
                      borderColor: "#ddd",
                      "&:hover": {
                        backgroundColor: "#f5f5f5",
                        borderColor: "#ccc",
                      },
                    }}
                  >
                    Cancel
                  </Button>
                </Box>
              </Paper>
            </Grid>
          ) : (
            <Grid item size={{ xs: 12, sm: 12, md: 6, lg: 6, xl: 6 }}>
              <Paper
                elevation={0}
                sx={{
                  p: 2,
                  borderRadius: 2,
                  background: "#f9f9f9",
                  height: "100%",
                  display: "flex",
                  flexDirection: "column",
                  justifyContent: "space-between",
                }}
              >
                <Box>
                  <Typography
                    variant="h6"
                    fontWeight={600}
                    gutterBottom
                    sx={{
                      color: "#333",
                      borderBottom: "2px solid #43B02A",
                      pb: 0.5,
                      mb: 2,
                      fontSize: "24px",
                    }}
                  >
                    Account Actions
                  </Typography>

                  <Typography variant="body2" color="#666" mb={2}>
                    Update your profile information or manage your account
                    settings.
                  </Typography>
                </Box>

                <Button
                  variant="contained"
                  onClick={handleEditToggle}
                  fullWidth
                  sx={{
                    py: 1,
                    borderRadius: 2,
                    textTransform: "none",
                    fontSize: "0.875rem",
                    fontWeight: 600,
                    backgroundColor: "#43B02A",
                    "&:hover": {
                      backgroundColor: "#3a9c26",
                      boxShadow: "0 2px 6px rgba(67, 176, 42, 0.3)",
                    },
                  }}
                >
                  Edit Profile
                </Button>
              </Paper>
            </Grid>
          )}
        </Grid>
      </Paper>

      <Snackbar
        open={snackbar.open}
        autoHideDuration={3000}
        onClose={handleSnackbarClose}
        anchorOrigin={{ vertical: "top", horizontal: "right" }}
      >
        <Alert
          onClose={handleSnackbarClose}
          severity={snackbar.severity}
          sx={{
            width: "100%",
            fontSize: "0.875rem",
            fontWeight: 500,
            boxShadow: "0 2px 8px rgba(0,0,0,0.15)",
            ...(snackbar.severity === "success" && {
              backgroundColor: "#43B02A",
              color: "white",
            }),
            ...(snackbar.severity === "error" && {
              backgroundColor: "#e53935",
              color: "white",
            }),
          }}
          iconMapping={{
            success: <SaveIcon fontSize="inherit" />,
            error: <SaveIcon fontSize="inherit" />,
          }}
        >
          {snackbar.message}
        </Alert>
      </Snackbar>
    </Container>
  );
};

export default Profile;
